package com.aadil.ecommerce;import com.aadil.ecommerce.dtos.UserRequestDTO;import com.aadil.ecommerce.dtos.UserResponseDTO;import com.aadil.ecommerce.entities.UserEntity;import com.aadil.ecommerce.exceptions.UserAlreadyExistsException;import com.aadil.ecommerce.repositories.UserRepository;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;@Servicepublic class UserService {    private final PasswordEncoder passwordEncoder;    private final UserRepository userRepository;    public UserService(PasswordEncoder passwordEncoder, UserRepository userRepository) {        this.passwordEncoder = passwordEncoder;        this.userRepository = userRepository;    }    public UserResponseDTO mapToDTO (UserEntity user){        return new UserResponseDTO(user.getId(),user.getName(),user.getEmail(),user.getRole());    }    public UserResponseDTO registerUser (UserRequestDTO dto){        String email = dto.getEmail().trim().toLowerCase();        if (userRepository.findByEmail(email).isPresent()){            throw new UserAlreadyExistsException("USER_ALREADY_REGISTERED");        }        String hashedPassword = passwordEncoder.encode(dto.getPassword());        UserEntity user = new UserEntity();        user.setName(dto.getName());        user.setEmail(email);        user.setPassword(hashedPassword);        user.setRole(UserRole.USER);       UserEntity savedUser = userRepository.save(user);       return mapToDTO(savedUser);    }}